-- Part 1: switches
select set_config('mgb.tk_owner_override', 'on', true);
insert into tk_settings (key, value) values ('mgb_home_enabled', 'true') on conflict (key) do update set value = excluded.value;
insert into tk_settings (key, value) values ('reviewboard_enabled', 'true') on conflict (key) do update set value = excluded.value;
insert into tk_settings (key, value) values ('desk_peek_enabled', 'true') on conflict (key) do update set value = excluded.value;
insert into tk_settings (key, value) values ('deskplus_enabled', 'true') on conflict (key) do update set value = excluded.value;
insert into tk_settings (key, value) values ('threadmenu_enabled', 'true') on conflict (key) do update set value = excluded.value;
insert into tk_settings (key, value) values ('org_contacts_enabled', 'true') on conflict (key) do update set value = excluded.value;

